        buffer << ",\"deferredPayloadIndexPersistenceEnabled\":" << (IsDeferredPayloadIndexPersistenceEnabled() ? "true" : "false");
        buffer << ",\"inlineAcceptancePayloadEnabled\":" << (IsInlineAcceptancePayloadEnabled() ? "true" : "false");
